#!/usr/bin/env python3
"""Apply the Package 6 verified protective-withdrawal correction."""

from __future__ import annotations

import argparse
import base64
from datetime import datetime
import hashlib
from pathlib import Path
import py_compile
import shutil
import tempfile
import zlib


FILES = {'src/thesis_core/thesis_core/horizon_clearance.py': {'expected': 'e48f512cc83454f5692398452e07a002ef85b8af0850bd0f6554a94a40d90905',
                                                      'desired': '413cd2d15e94319b4d3aaa8439255ce42c282e004203f146660346689bcbb23f',
                                                      'payload': ''},
 'src/thesis_core/thesis_core/safety_policy.py': {'expected': '57966db117a08126bbc9bd42bb6d0acb890b69cfc006a1bfad59ec01a93d46e2',
                                                  'desired': '9220646854c9d4176100680f3dc1561bafe756857041a1ac52df5aa9e3adcbed',
                                                  'payload': ''},
 'src/thesis_core/thesis_core/safety_supervisor_node.py': {'expected': '9ecbe45bf67ad1b06e9f94546612a48aab937d661b443b62182cbbc0cbdea4d0',
                                                           'desired': 'aab829639768dace890c98d45f5f2edeb25b45ad6e6121543b2f5bf08674ed34',
                                                           'payload': ''},
 'src/thesis_core/test/test_safety_policy.py': {'expected': 'b3967a4c4398eab0281f5c5341fa54e7280453c4aafeb26b009b3809e9f823ec',
                                                'desired': '291e9b6115f2c44fb512963ffaed7d0fc402c9d608a47e7d4f6a8ba22691898b',
                                                'payload': ''}}


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        '--workspace',
        type=Path,
        default=Path.home() / 'Escritorio' / 'TESIS_2_IMPLEMENTATION',
    )
    return parser.parse_args()


def main() -> int:
    workspace = parse_args().workspace.resolve()
    if not workspace.is_dir():
        raise SystemExit(f'ERROR: workspace inexistente: {workspace}')

    desired = {
        relative: zlib.decompress(base64.b64decode(metadata['payload']))
        for relative, metadata in FILES.items()
    }
    pending = []
    for relative, metadata in FILES.items():
        target = workspace / relative
        if not target.is_file():
            raise SystemExit(f'ERROR: falta archivo requerido: {target}')
        current_hash = digest(target.read_bytes())
        if current_hash == metadata['desired']:
            print(f'YA_ACTUALIZADO={relative}')
            continue
        if current_hash != metadata['expected']:
            raise SystemExit(
                f'ERROR: hash inesperado en {target}\n'
                f'actual={current_hash}\n'
                f'esperado={metadata["expected"]}\n'
                'No se modificó ningún archivo.'
            )
        pending.append(relative)

    for relative, data in desired.items():
        if relative.endswith('.py'):
            compile(data, str(workspace / relative), 'exec')

    if not pending:
        print('RESULTADO_APLICACION=YA_APLICADO')
        return 0

    backup = (
        Path.home()
        / 'RESPALDO_TESIS_PAQUETE6_RETIRADA'
        / datetime.now().strftime('%Y%m%d_%H%M%S')
    )
    backup.mkdir(parents=True, exist_ok=False)

    for relative in pending:
        target = workspace / relative
        destination = backup / relative
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(target, destination)

    for relative in pending:
        target = workspace / relative
        with tempfile.NamedTemporaryFile(
            mode='wb',
            dir=target.parent,
            prefix=f'.{target.name}.retirada.',
            delete=False,
        ) as stream:
            stream.write(desired[relative])
            temporary = Path(stream.name)
        temporary.replace(target)

    for relative in FILES:
        if relative.endswith('.py'):
            py_compile.compile(str(workspace / relative), doraise=True)

    print(f'RESPALDO={backup}')
    for relative in FILES:
        target = workspace / relative
        print(f'SHA256={digest(target.read_bytes())}  {relative}')
    print('RESULTADO_APLICACION=PASS')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
